@prefix sh: <http://www.w3.org/ns/shacl#> .
@prefix sosa: <http://www.w3.org/ns/sosa/> .
@prefix xsd: <http://www.w3.org/2001/XMLSchema#> .

[] a sh:ValidationReport ;
    sh:conforms false ;
    sh:result [ a sh:ValidationResult ;
            sh:focusNode <https://example.org/closure/ip68-characteristics> ;
            sh:resultMessage "sosa:observedProperty is required, on the collection, a collection it is a member of, or its members" ;
            sh:resultPath sosa:observedProperty ;
            sh:resultSeverity sh:Violation ;
            sh:sourceConstraint [ sh:message "sosa:observedProperty is required, on the collection, a collection it is a member of, or its members" ;
                    sh:select """
            PREFIX sosa: <http://www.w3.org/ns/sosa/>
            PREFIX geojson: <https://purl.org/geojson/vocab#>
            SELECT $this (sosa:observedProperty AS ?path) WHERE {
                FILTER NOT EXISTS {
                    { $this (^sosa:hasMember|^geojson:features|sosa:memberOf)* ?holder }
                    UNION
                    {
                        $this (sosa:hasMember|geojson:features|^sosa:memberOf)+ ?member .
                        ?member (^sosa:hasMember|^geojson:features|sosa:memberOf)* ?holder .
                    }
                    ?holder sosa:observedProperty ?prop .
                }
            }
        """ ] ;
            sh:sourceConstraintComponent sh:SPARQLConstraintComponent ;
            sh:sourceShape <https://www.ogc.org/rules/sosa/#testObservedPropertyConsistent> ;
            sh:value <https://example.org/closure/ip68-characteristics> ] .

